// Process the filtered emails
// You can add custom processing here

const filteredEmails = [];

for (const item of $input.all()) {
  filteredEmails.push({
    id: item.json.id,
    subject: item.json.Subject,
    from: item.json.From,
    date: item.json.internalDate,
    snippet: item.json.snippet
  });
}

return filteredEmails;

// Summary of labeled emails
const items = $input.all();
const summary = {
  totalLabeled: items.length,
  labeledEmails: items.map(item => ({
    subject: item.json.Subject || item.json.subject,
    from: item.json.From || item.json.from,
    id: item.json.id
  }))
};

console.log(`Labeled ${summary.totalLabeled} emails with 'Facebook-Excluded-People' label`);

return [summary];
